  test "repair generated IDs and ordering are stable across input row permutations" do
    activities = [
      downlink("dl_1", 100.0, 160.0),
      observe("obs_1", "leo_1", "target_a", 250.0, 310.0, 10.0)
    ]

    candidates = [
      downlink("dl_2", 700.0, 760.0),
      observe("obs_2", "leo_1", "target_a", 800.0, 860.0, 12.0)
    ]

    realized_activities = [
      %{id: "obs_1", status: "failed"},
      %{id: "dl_1", status: "missed"}
    ]

    request_for = fn activities, candidates, realized_activities ->
      %ReplanRequest{
        prior_plan:
          base_plan(%{
            "activities" => activities,
            "candidate_activities" => candidates
          }),
        realized_state: %{activities: realized_activities},
        current_epoch_s: 165.0,
        generated_at: ~U[2026-05-13 12:00:00Z]
      }
    end

    left = CampaignPlanner.repair(request_for.(activities, candidates, realized_activities))

    right =
      CampaignPlanner.repair(
        request_for.(
          Enum.reverse(activities),
          Enum.reverse(candidates),
          Enum.reverse(realized_activities)
        )
      )

    assert right == left

    assert Enum.map(left["source_candidate_activities"], & &1["id"]) == [
             "dl_2",
             "obs_2"
           ]

    assert Enum.map(left["deltas"], & &1["activity_id"]) == ["dl_1", "obs_1"]
  end

  test "strategy compares baseline against ground-station outage branch" do
    prior_plan =
      base_plan(%{
        "planning_horizon" => %{"duration_s" => 1_500.0},
        "assumptions" => %{
          "constraints" => %{"max_timeline_activities" => 0, "min_activity_duration_s" => 90.0},
          "scoring_policy" => %{}
        },
        "activities" => [downlink("dl_1", 100.0, 160.0)],
        "candidate_activities" => [
          downlink("dl_1", 100.0, 160.0),
          downlink("dl_2", 700.0, 760.0)
        ]
      })

    artifact =
      strategy(prior_plan,
        mission_state:
          mission_state([%{"type" => "downlink_completion", "required_contacts" => 1}]),
        branches: [
          %{id: "baseline", label: "Nominal"},
          %{
            id: "station_outage",
            label: "Station outage",
            events: [
              %{
                type: "ground_station_outage",
                station_id: :equator_prime,
                start_s: "90.0",
                end_s: "200.0"
              }
            ]
          },
          %{id: "noop", probability: 0.0}
        ],
        current_epoch_s: 0.0
      )

    outage = branch(artifact, "station_outage")

    assert [
             %{
               "type" => "ground_station_outage",
               "ground_station_id" => "equator_prime",
               "starts_at_s" => 90.0,
               "ends_at_s" => 200.0
             }
           ] = outage["events"]

    refute Map.has_key?(List.first(outage["events"]), "station_id")
    refute Map.has_key?(List.first(outage["events"]), "start_s")
    refute Map.has_key?(List.first(outage["events"]), "end_s")

    assert artifact["recommendation"]["recommended_branch_id"] == "baseline"
    assert Enum.any?(outage["risk_indicators"], &(&1["type"] == "ground_station_outage"))

    assert [
             %{
               "activity_id" => "dl_1",
               "repair_action" => "moved",
               "replacement_activity_id" => "dl_2"
             }
           ] = outage["repair_result"]["deltas"]

    outage_row =
