      })

    artifact =
      strategy(prior_plan,
        branches: [
          %{id: "baseline"},
          %{
            id: "degraded",
            events: [
              %{
                type: "degraded_spacecraft",
                scenario_id: "leo_1",
                incompatible_activity_types: ["observe"]
              }
            ]
          }
        ],
        current_epoch_s: 0.0
      )

    degraded = branch(artifact, "degraded")

    assert [%{"activity_id" => "obs_1", "repair_action" => "suppressed"}] =
