             "planned_downlink_mb" => 40.0,
             "required_contacts" => 1,
             "planned_contacts" => 1
           } = List.first(downlink_branch["events"])

    additions = downlink_branch["candidate_plan"]["strategic_additions"]

    assert %{
             "feasibility" => %{
               "required_downlink_mb" => 120.0,
               "planned_downlink_mb" => 40.0,
               "staged_downlink_mb" => 90.0,
               "candidate_downlink_mb" => 30.0
