                target_id: "target_hot",
                starts_at_s: 500.0,
                ends_at_s: 560.0
              }
            ]
          },
          %{
            id: "urgent_cold",
            events: [
              %{
                type: "urgent_target",
                target_id: "target_cold",
                starts_at_s: 600.0,
                ends_at_s: 660.0
              }
            ]
          }
