                 &1["event_type"] == "urgent_target" and &1["target_id"] == "target_hot")
           )

    refute Enum.any?(
             urgent_cold["approval_rule_matches"],
             &(&1["rule_id"] == "urgent_hot_event_review")
           )
  end

