    for source_path <- [
          "mission_state.source_contact_allocation_summary",
          "mission_state.source_contact_allocation_station_pressure_summary",
          "mission_state.source_contact_allocation_reservation_conflict_summary",
          "mission_state.source_contact_allocation_provider_reservation_request_summary"
        ] do
      assert source_path in contact_allocation_source_paths
    end

    station_calendar_replay_summary =
      CandidateRefresh.station_calendar_replay_summary(candidate_source)

    assert %{
             "branch_local_station_calendar_pressure" => true,
             "branch_local_affected_contact_pressure" => true,
             "branch_local_provider_contention_pressure" => true,
             "station_calendar_status_counts" => %{"reserved" => 1},
             "affected_contact_availability_counts" => %{"reserved" => 1},
             "provider_calendar_contention_group_count" => 1,
             "affected_contact_ids" => [^challenge_contact],
             "affected_station_reservation_ids" => ["challenge_reservation_1"],
             "source_report_paths" => station_calendar_source_paths
           } = station_calendar_replay_summary

    assert "mission_state.source_station_calendar_report" in station_calendar_source_paths

    station_reservation_replay_summary =
      CandidateRefresh.station_reservation_replay_summary(candidate_source)

    assert %{
             "branch_local_station_reservation_pressure" => true,
             "branch_local_reservation_review_pressure" => true,
             "branch_local_reservation_hold_import_readiness_pressure" => true,
             "station_reservation_match_status_counts" => %{"overlap" => 1},
             "reservation_ids" => reservation_ids,
             "reservation_hold_import_readiness_status_counts" => %{
               "review_required" => 1
             },
             "reservation_hold_import_status_counts" => %{
               "review_required_before_import" => 2
             },
             "source_report_paths" => station_reservation_source_paths
           } = station_reservation_replay_summary

    assert "challenge_reservation_1" in reservation_ids
    assert "challenge_provider_hold" in reservation_ids

    assert challenge_contact in station_reservation_replay_summary["affected_contact_ids"]

    assert challenge_contact in get_in(
             station_reservation_replay_summary,
             ["reservation_hold_contact_ids_by_import_status", "review_required_before_import"]
           )

    assert "mission_state.source_station_reservation_report" in station_reservation_source_paths

    assert "mission_state.source_station_reservation_hold_import_readiness_summary" in station_reservation_source_paths

    assert challenge_branch["score_terms"]["contact_allocation_pressure_penalty"] < 0.0

    assert "contact_allocation_pressure_penalty" in artifact["score_term_report"][
             "score_term_keys"
           ]

    assert Enum.any?(
             artifact["score_term_report"]["rows"],
             &(&1["branch_id"] == "challenge" and
                 &1["term_key"] == "contact_allocation_pressure_penalty" and
                 &1["value"] < 0.0)
           )

    challenge_row =
      artifact["branch_comparison_report"]["rows"]
      |> Enum.find(&(&1["branch_id"] == "challenge"))

    assert "downlink_completion_gap" in challenge_row["risk_types"]
    assert "provider_reservation_request_review" in challenge_row["risk_types"]

    assert challenge_row["branch_station_reservation_conflict_contact_ids"] == [
             challenge_contact,
             "challenge_dl_review_overlap"
           ]

    assert challenge_row["branch_station_reservation_conflict_reservation_ids"] == [
             "challenge_reservation_1",
             "challenge_reservation_review"
           ]

    assert {:ok, %{"schema_contract" => "campaign_strategy.v3", "status" => "pass"}} =
             Schema.validate_artifact(artifact)
  end

  test "strategy derives branch refresh requests from rich mission state" do
    mission_state =
      mission_state_with_refresh_inputs()
      |> put_in([:candidate_refresh_defaults, :candidate_limit_policy], %{
        max_candidate_activities: 1
      })

    artifact =
      strategy(base_plan(%{"activities" => [downlink("dl_1", 100.0, 160.0)]}),
        mission_state: mission_state,
        branches: [
          %{id: "baseline"},
          %{
            id: "urgent",
            events: [%{type: "urgent_target", target_id: "target_a", priority: 12.0}]
          }
        ],
        current_epoch_s: 0.0
      )

    urgent = branch(artifact, "urgent")

    assert %{
             "type" => "candidate_refresh.v1",
             "snapshot_id" => "ops-rich",
             "scope" => "branch_generated"
           } = urgent["assumptions"]["candidate_source"]

    assert urgent["repair_result"]["repair_metadata"]["candidate_window_count"] > 0

    assert %{
             "schema_contract" => "refresh_budget_report.v1",
             "max_candidate_activities" => 1,
             "dropped_candidate_count" => 1,
             "kept_candidate_count" => 1
           } = urgent["repair_result"]["source_refresh_budget_report"]

    assert %{
             "branch_id" => "urgent",
             "review_type" => "refresh_budget_review",
             "source" => "campaign_strategy.branches.repair_result.source_refresh_budget_report",
             "required_operator_action" => "review_refresh_budget",
             "dropped_candidate_count" => 1,
             "source_refresh_budget_report" => %{"schema_contract" => "refresh_budget_report.v1"}
           } =
             Enum.find(
               artifact["operator_review_package"]["rows"],
               &(&1["review_type"] == "refresh_budget_review" and &1["branch_id"] == "urgent")
             )

    assert %{
             "branch_id" => "urgent",
             "import_action" => "review_refresh_budget",
             "source_review_type" => "refresh_budget_review",
             "dropped_candidate_count" => 1,
             "import_status" => "review_required_before_import"
           } =
             Enum.find(
               artifact["cadence_import_manifest"]["rows"],
               &(&1["import_action"] == "review_refresh_budget" and &1["branch_id"] == "urgent")
             )

    assert length(urgent["repair_result"]["source_candidate_activities"]) == 1

    assert Enum.any?(
             urgent["repair_result"]["source_candidate_activities"],
             &(&1["type"] == "observe" and &1["target_id"] == "target_a")
           )

    assert urgent["provenance"]["candidate_source"]["scope"] == "branch_generated"
  end

  test "strategy stages urgent targets from branch-generated refresh candidates" do
    artifact =
      strategy(base_plan(%{}),
        mission_state: mission_state_with_refresh_inputs(),
        branches: [
          %{id: "baseline"},
          %{
            id: "urgent",
            events: [%{type: "urgent_target", target_id: "target_a", priority: 12.0}]
          }
        ],
        current_epoch_s: 0.0
      )

    urgent = branch(artifact, "urgent")

    assert [
             %{
               "id" => "urgent_urgent_observe_target_a",
               "target_id" => "target_a",
               "feasibility" => %{
                 "status" => "validated_candidate_window",
                 "source_window" => %{
                   "type" => "target_visibility"
                 }
               }
             }
           ] = urgent["candidate_plan"]["strategic_additions"]

    refute Enum.any?(urgent["warnings"], &String.contains?(&1, "unvalidated placeholder"))
    refute Enum.any?(urgent["risk_indicators"], &(&1["type"] == "urgent_target_unvalidated"))
  end

