    assert %{
             "type" => "relay_data_path_pressure",
             "severity" => "high",
             "route_id" => "route_direct",
             "feedback_source" => "mission_state.source_relay_data_path_summary",
             "trust_boundary" => "direct_relay_boundary"
           } =
