    risk_weight = get_in(artifact, ["score_term_report", "assumptions", "policy", "risk_weight"])

    assert urgent["score_terms"]["timeline_dependency_impact_pressure_penalty"] ==
             -timeline_dependency_impact_pressure_count * risk_weight

