              required_states: [
                %{
                  subsystem: "commanding",
                  state: "armed",
                  reason: "template requires armed commanding state"
                }
              ]
            }
          }
        }
      })
      |> Map.put("provenance", %{"trust_boundary" => "branch_precondition_boundary"})

    assert {:ok, %{"schema_contract" => "timeline_activity_precondition_summary.v1"}} =
             Schema.validate_artifact(precondition_summary)

    artifact =
      strategy(base_plan(%{}),
        mission_state:
          mission_state_with_refresh_inputs()
          |> Map.put("source_timeline_activity_precondition_summary", precondition_summary),
        branches: [
          %{id: "baseline"},
          %{
            id: "urgent",
            events: [%{type: "urgent_target", target_id: "target_a", priority: 12.0}]
          }
        ],
        current_epoch_s: 0.0
      )

    urgent = branch(artifact, "urgent")

    assert %{"type" => "candidate_refresh.v1", "scope" => "branch_generated"} =
             candidate_source = urgent["assumptions"]["candidate_source"]

    assert "mission_state.source_timeline_activity_precondition_summary" in candidate_source[
             "source_report_input_paths"
           ]

    assert "mission_state.source_timeline_activity_precondition_summary" in candidate_source[
             "candidate_refresh_request_source_report_input_paths"
           ]

    assert %{
             "source" =>
               "candidate_refresh.candidate_source.candidate_refresh_request_source_report_summary.timeline_activity_precondition_summary",
             "contract" => "timeline_activity_precondition_summary.v1",
             "source_report_count" => 1,
             "source_report_row_count" => 7,
             "source_report_paths" => [
               "mission_state.source_timeline_activity_precondition_summary"
             ],
             "blocked_precondition_count" => 3,
             "review_precondition_count" => 4,
             "blocked_precondition_type_counts" => %{
               "command_safety_failed" => 1,
               "payload_unavailable" => 1,
               "resource_block_declared" => 1
             },
             "review_precondition_type_counts" => %{
               "command_authority_missing" => 1,
               "command_safety_unchecked" => 1,
               "degraded_mode" => 1,
               "subsystem_state_required" => 1
             },
             "activity_id_counts" => %{"branch_precondition_cmd_precondition" => 2},
             "timeline_id_counts" => %{"timeline:branch_precondition:cmd_precondition" => 2},
             "dependency_activity_id_counts" => %{"health_check" => 1},
             "dependency_timeline_id_counts" => %{"timeline:health_check" => 1},
             "duplicate_dependency_activity_id_counts" => %{"health_check" => 1},
             "exclusive_with_activity_id_counts" => %{"downlink_conflict" => 1},
             "exclusive_with_timeline_id_counts" => %{"timeline:downlink_conflict" => 1},
             "duplicate_exclusivity_activity_id_counts" => %{"downlink_conflict" => 1},
             "branch_local_timeline_activity_precondition_pressure" => true,
             "branch_local_activity_precondition_review_pressure" => true,
             "branch_local_activity_precondition_dependency_pressure" => true,
             "branch_local_activity_precondition_exclusivity_pressure" => true
           } = CandidateRefresh.timeline_activity_precondition_replay_summary(candidate_source)

    precondition_pressure_count =
      Enum.count(
        urgent["risk_indicators"],
        &(&1["type"] == "timeline_activity_precondition_review" and
            &1["feedback_source"] ==
              "candidate_source.timeline_activity_precondition_replay_summary")
      )

    assert precondition_pressure_count == 1

    assert Enum.any?(
             urgent["risk_indicators"],
             &(&1["type"] == "timeline_activity_precondition_review" and
                 &1["blocked_precondition_count"] == 3 and
                 &1["review_precondition_count"] == 4 and
                 &1["blocked_precondition_types"] == [
                   "command_safety_failed",
                   "payload_unavailable",
                   "resource_block_declared"
                 ] and
                 &1["review_precondition_types"] == [
                   "command_authority_missing",
                   "command_safety_unchecked",
                   "degraded_mode",
                   "subsystem_state_required"
                 ] and
                 &1["activity_ids"] == ["branch_precondition_cmd_precondition"] and
                 &1["dependency_activity_ids"] == ["health_check"] and
                 &1["duplicate_dependency_activity_ids"] == ["health_check"] and
                 &1["exclusive_with_activity_ids"] == ["downlink_conflict"] and
                 &1["duplicate_exclusivity_activity_ids"] == ["downlink_conflict"] and
                 &1["feedback_scope"] == "timeline_activity_precondition")
           )

    risk_weight = get_in(artifact, ["score_term_report", "assumptions", "policy", "risk_weight"])

    assert urgent["score_terms"]["timeline_precondition_pressure_penalty"] ==
             -precondition_pressure_count * risk_weight

    assert "timeline_precondition_pressure_penalty" in artifact["score_term_report"][
             "score_term_keys"
           ]

    assert Enum.any?(
             artifact["score_term_report"]["rows"],
             &(&1["branch_id"] == urgent["branch_id"] and
                 &1["term_key"] == "timeline_precondition_pressure_penalty" and
                 &1["value"] < 0.0)
           )

    assert {:ok, %{"schema_contract" => "campaign_strategy.v3", "status" => "pass"}} =
             Schema.validate_artifact(artifact)
  end

  test "strategy derives branch pressure from timeline integrity reports" do
    integrity_report = fn activity_id, missing_activity_id, source, trust_boundary ->
      Timeline.integrity_report(
        [
          %{
            id: activity_id,
            type: :command,
            starts_at_s: 10.0,
            ends_at_s: 20.0,
            dependency_activity_ids: [missing_activity_id],
            metadata: %{timeline_id: :"timeline:#{activity_id}"}
          }
        ],
        source: source
      )
      |> Map.put("provenance", %{"trust_boundary" => trust_boundary})
    end

    prior_integrity_report =
      integrity_report.(
        :cmd_prior_integrity,
        :missing_prior_gate,
        "prior.timeline_integrity",
        "prior_integrity_boundary"
      )

    prior_wrapped_report =
      integrity_report.(
        :cmd_prior_wrapped_integrity,
        :missing_prior_wrapped_gate,
        "prior.wrapped_timeline_integrity",
        "prior_wrapped_integrity_boundary"
      )
      |> Map.delete("provenance")

    prior_bare_report =
      integrity_report.(
        :cmd_prior_bare_integrity,
        :missing_prior_bare_gate,
        "prior.bare_timeline_integrity",
        "prior_bare_integrity_boundary"
      )

    duplicate_direct_report =
      integrity_report.(
        :cmd_duplicate_integrity,
        :missing_duplicate_direct_gate,
        "prior.duplicate_direct_timeline_integrity",
        "duplicate_direct_integrity_boundary"
      )

    duplicate_wrapped_report =
      integrity_report.(
        :cmd_duplicate_integrity,
        :missing_duplicate_wrapped_gate,
        "prior.duplicate_wrapped_timeline_integrity",
        "duplicate_wrapped_integrity_boundary"
      )
      |> Map.delete("provenance")

    mission_integrity_report =
      integrity_report.(
        :cmd_live_integrity,
        :missing_live_gate,
        "mission.timeline_integrity",
        "mission_integrity_boundary"
      )
      |> Map.delete("provenance")

    prior_plan =
      base_plan(%{
        "source_timeline_integrity_report" => [prior_integrity_report, duplicate_direct_report],
        "source_result_artifact" => %{
          "schema_contract" => "result_artifact.v1",
          "artifact_type" => "prior_plan_result_artifact",
          "timeline_integrity_report" => [prior_wrapped_report, duplicate_wrapped_report],
          "provenance" => %{"trust_boundary" => "prior_wrapped_integrity_artifact_boundary"}
        },
        "result_artifact" => prior_bare_report
      })

    mission_state =
      mission_state_with_refresh_inputs()
      |> Map.put(:source_result_artifact, %{
        "schema_contract" => "result_artifact.v1",
        "artifact_type" => "mission_state_result_artifact",
        "timeline_integrity_report" => mission_integrity_report,
        "provenance" => %{"trust_boundary" => "mission_integrity_artifact_boundary"}
      })

    artifact =
      strategy(prior_plan,
        mission_state: mission_state,
        derive_branches?: true,
        branches: [%{id: "baseline"}],
        current_epoch_s: 0.0
      )

    prior_branch =
      branch(artifact, "derived_timeline_integrity_pressure_cmd_prior_integrity")

    assert %{
             "type" => "timeline_integrity_feedback",
             "activity_id" => "cmd_prior_integrity",
             "missing_dependency_activity_ids" => ["missing_prior_gate"],
             "feedback_source" => "prior_plan.source_timeline_integrity_report[0].rows",
             "feedback_scope" => "timeline_integrity",
             "trust_boundary" => "prior_integrity_boundary",
             "derivation_reasons" => ["timeline_integrity_report_pressure"]
           } = List.first(prior_branch["events"])

    assert Enum.any?(
             prior_branch["risk_indicators"],
             &(&1["type"] == "timeline_integrity_issue" and
                 &1["severity"] == "high" and
                 &1["missing_dependency_activity_ids"] == ["missing_prior_gate"] and
                 &1["feedback_source"] == "prior_plan.source_timeline_integrity_report[0].rows")
           )

    risk_weight = get_in(artifact, ["score_term_report", "assumptions", "policy", "risk_weight"])

    timeline_integrity_pressure_count =
      Enum.count(prior_branch["risk_indicators"], &(&1["type"] == "timeline_integrity_issue"))

    assert timeline_integrity_pressure_count == 1

    assert prior_branch["score_terms"]["timeline_integrity_pressure_penalty"] ==
             -timeline_integrity_pressure_count * risk_weight

    assert prior_branch["score_terms"]["timeline_pressure_penalty"] == 0.0

    assert prior_branch["score_terms"]["risk_penalty"] ==
             -(length(prior_branch["risk_indicators"]) - timeline_integrity_pressure_count) *
               risk_weight

    assert "timeline_integrity_pressure_penalty" in artifact["score_term_report"][
             "score_term_keys"
           ]

    assert "timeline_pressure_penalty" in artifact["score_term_report"]["score_term_keys"]

    assert Enum.any?(
             artifact["score_term_report"]["rows"],
             &(&1["branch_id"] == "derived_timeline_integrity_pressure_cmd_prior_integrity" and
                 &1["term_key"] == "timeline_integrity_pressure_penalty" and &1["value"] < 0.0)
           )

    prior_row =
      artifact["branch_comparison_report"]["rows"]
      |> Enum.find(
        &(&1["branch_id"] == "derived_timeline_integrity_pressure_cmd_prior_integrity")
      )

    assert prior_row["branch_timeline_integrity_activity_ids"] == ["cmd_prior_integrity"]
    assert prior_row["branch_missing_dependency_activity_ids"] == ["missing_prior_gate"]
    assert prior_row["branch_feedback_scopes"] == ["timeline_integrity"]

    prior_wrapped_branch =
      branch(artifact, "derived_timeline_integrity_pressure_cmd_prior_wrapped_integrity")

    assert %{
             "activity_id" => "cmd_prior_wrapped_integrity",
             "missing_dependency_activity_ids" => ["missing_prior_wrapped_gate"],
             "feedback_source" =>
               "prior_plan.source_result_artifact.timeline_integrity_report[0].rows",
             "trust_boundary" => "prior_wrapped_integrity_artifact_boundary"
           } = List.first(prior_wrapped_branch["events"])

    prior_bare_branch =
      branch(artifact, "derived_timeline_integrity_pressure_cmd_prior_bare_integrity")

    assert %{
             "activity_id" => "cmd_prior_bare_integrity",
             "missing_dependency_activity_ids" => ["missing_prior_bare_gate"],
             "feedback_source" => "prior_plan.result_artifact.rows",
             "trust_boundary" => "prior_bare_integrity_boundary"
           } = List.first(prior_bare_branch["events"])

    duplicate_branches =
      artifact["branch_comparison_report"]["rows"]
      |> Enum.map(& &1["branch_id"])
      |> Enum.filter(fn branch_id ->
        String.starts_with?(
          branch_id,
          "derived_timeline_integrity_pressure_cmd_duplicate_integrity"
        )
      end)

    assert length(duplicate_branches) == 2

    assert duplicate_branches
           |> Enum.uniq()
           |> length() == 2

    assert duplicate_branches
           |> Enum.map(&(artifact |> branch(&1) |> Map.get("events") |> List.first()))
           |> Enum.map(& &1["feedback_source"])
           |> Enum.sort() == [
             "prior_plan.source_result_artifact.timeline_integrity_report[1].rows",
             "prior_plan.source_timeline_integrity_report[1].rows"
           ]

    mission_branch =
      branch(artifact, "derived_timeline_integrity_pressure_cmd_live_integrity")

    assert %{
             "type" => "timeline_integrity_feedback",
             "activity_id" => "cmd_live_integrity",
             "missing_dependency_activity_ids" => ["missing_live_gate"],
             "feedback_source" =>
               "mission_state.source_result_artifact.timeline_integrity_report.rows",
             "feedback_scope" => "timeline_integrity",
             "trust_boundary" => "mission_integrity_artifact_boundary"
           } = List.first(mission_branch["events"])

    assert Enum.any?(
             mission_branch["risk_indicators"],
             &(&1["type"] == "timeline_integrity_issue" and
                 &1["missing_dependency_activity_ids"] == ["missing_live_gate"] and
                 &1["trust_boundary"] == "mission_integrity_artifact_boundary")
           )

    assert {:ok, %{"schema_contract" => "campaign_strategy.v3", "status" => "pass"}} =
             Schema.validate_artifact(artifact)
  end

  test "strategy derives branch pressure from timeline lifecycle state summaries" do
    lifecycle_summary = fn prefix, trust_boundary ->
      planned = [
        %{
          id: :"#{prefix}_cmd_pending",
          type: :command,
          status: :planned,
          approval_status: :pending,
          starts_at_s: 10.0,
          ends_at_s: 20.0,
          metadata: %{timeline_id: "timeline:#{prefix}:cmd_pending"}
        },
        %{
          id: :"#{prefix}_dup_a",
          type: :observe,
          status: :planned,
          starts_at_s: 30.0,
          ends_at_s: 40.0,
          metadata: %{timeline_id: "timeline:#{prefix}:dup"}
        },
        %{
          id: :"#{prefix}_dup_b",
          type: :observe,
          status: :planned,
          starts_at_s: 35.0,
          ends_at_s: 45.0,
          metadata: %{timeline_id: "timeline:#{prefix}:dup"}
        },
        %{
          id: :"#{prefix}_bad_missing_type",
          status: :planned,
          starts_at_s: 50.0,
          ends_at_s: 60.0,
          metadata: %{timeline_id: "timeline:#{prefix}:bad_missing_type"}
        }
      ]

      realized = [
        %{
          id: :"#{prefix}_cmd_pending",
          type: :command,
          status: :executed,
          approval_status: :approved,
          starts_at_s: 10.0,
          ends_at_s: 20.0,
          metadata: %{timeline_id: "timeline:#{prefix}:cmd_pending"}
        }
      ]

      planned
      |> Timeline.lifecycle_state_summary(realized, source: "mission.#{prefix}.lifecycle")
      |> Map.put("provenance", %{"trust_boundary" => trust_boundary})
    end

    direct_summary = lifecycle_summary.("direct_lifecycle", "direct_lifecycle_boundary")
    canonical_summary = lifecycle_summary.("canonical_lifecycle", "canonical_lifecycle_boundary")

    wrapped_summary =
      lifecycle_summary.("wrapped_lifecycle", "wrapped_lifecycle_boundary")
      |> Map.delete("provenance")

    assert {:ok, %{"schema_contract" => "timeline_lifecycle_state_summary.v1"}} =
             Schema.validate_artifact(direct_summary)

    mission_state =
      mission_state_with_refresh_inputs()
      |> Map.put("source_timeline_lifecycle_state_summary", direct_summary)
      |> Map.put("timeline_lifecycle_state_summary", canonical_summary)
      |> Map.put(:source_result_artifact, %{
        "schema_contract" => "result_artifact.v1",
        "artifact_type" => "mission_state_result_artifact",
        "timeline_lifecycle_state_summary" => wrapped_summary,
        "provenance" => %{"trust_boundary" => "wrapped_lifecycle_artifact_boundary"}
      })

    artifact =
      strategy(base_plan(%{}),
        mission_state: mission_state,
        derive_branches?: true,
        branches: [%{id: "baseline"}],
        current_epoch_s: 0.0
      )

    direct_branch =
      branch(
