      %{
        "schema_contract" => "operational_timeline_report.v1",
        "source" => "campaign_planner_test.#{prefix}.operational_timeline_report",
        "rows" => [
          %{
            "id" => "timeline_row:#{prefix}_timeline_activity",
            "activity_id" => "#{prefix}_timeline_activity",
