    event = List.first(degraded["events"])

    assert %{
             "type" => "degraded_spacecraft",
             "scenario_id" => "leo_1",
             "spacecraft_available" => false,
             "incompatible_activity_types" => ["downlink", "observe", "planned_contact"]
