              "scenario_id" => "leo_projection_canonical",
              "resource_source_quality" => "repaired_plan",
              "resource_trust_boundary_status" => "declared",
              "projected_storage_overflow_mb" => 12.0,
              "activity_resource_flow" => [
                %{
