        &(Map.get(&1, "branch_id") in [
            direct_readiness_branch["branch_id"],
            wrapped_readiness_branch["branch_id"],
            direct_quality_branch["branch_id"],
            wrapped_quality_branch["branch_id"]
          ])
      )

    assert Enum.any?(
